head.script:
scwin.gReqAcptNo; // 조회공시 요구접수번호
scwin.gAnsAcptNo; // 조회공시 답변접수번호

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
//
// ********************************************************************

scwin.gAcptNo;
scwin.gAnsRnd;
scwin.gAnsFormCd;
scwin.gAnsFormVer;
scwin.gIsurCd;
X < !정보--;
셋팅-- > function() {
    scwin.gReqAcptNo = $c.frame.path("../").scwin.gReqAcptNo;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    // alert(gReqAcptNo);

} < !정보--;
데이타;
읽어오기-- > async function() {
    const sbmOptions = {
        id : "sbm_dts_inquiryans_info",
        action : "/InquiryDisclosure.do",
        ref : "",
        target : "dts_inquiryans_info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        fn_GetParentValue();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_inquiryans_info",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_inquiryans_info=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        //  정보 읽어오기
        fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30201.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_inquiryans_info_OnLoadError
 * @description dts_inquiryans_info 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_inquiryans_info_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_inquiryans_info);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30201.dts_inquiryans_info_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        // self.close();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30201.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_inquiryans_info_OnDblClick
 * @description grd_inquiryans_info 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_inquiryans_info_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "ANS_DOC_TITLE") {
            await $c.stf.openDisclViewer(scwin.gAnsAcptNo, 'R');
        } else if (colid === "FINAL") {
            let url = "/dsclmgt/ULDSTF30202.gfm";
            let winTitle = "조회공시 답변관리";
            await $c.frame.CreateFrame("REQ_ANS" + scwin.gReqAcptNo, url, winTitle, 100, 10, 560, 290, "window", 0, 0, true);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30201.grd_inquiryans_info_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        let url = "/dsclmgt/ULDSTF30203.gfm";
        let winTitle = "조회공시 답변연결";
        await $c.frame.CreateFrame("REQ_ANS_NEW" + scwin.gReqAcptNo, url, winTitle, 50, 10, 810, 450 + 30, "window", 0, 0, true);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30201.btn_New_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gReqAcptNo = dts_inquiryans_info.getCellData(Number(obj), "REQ_ACPT_NO");
    scwin.gAnsRnd = dts_inquiryans_info.getCellData(Number(obj), "ANS_RND");
    scwin.gAnsAcptNo = dts_inquiryans_info.getCellData(Number(obj), "ANS_ACPT_NO");
    scwin.gAnsFormCd = dts_inquiryans_info.getCellData(Number(obj), "ANS_FORM_CD");
    scwin.gAnsFormVer = dts_inquiryans_info.getCellData(Number(obj), "ANS_FORM_VER");
    scwin.gIsurCd = dts_inquiryans_info.getCellData(Number(obj), "ISUR_CD");
    scwin.gAcptNo = scwin.gAnsAcptNo;
    // alert("부모창:"+gIsurCd);

};
